prompt:
Crie um componente Label para um projeto React + Tailwind CSS com shadcn/ui (estilo "New York", acessível via Radix UI).

Alternativa recomendada (registro oficial open source, licença MIT): instale direto com o CLI shadcn:

npx shadcn add label

Documentação oficial: https://ui.shadcn.com/docs/components/label

Implementação de referência (MIT — shadcn/ui):

"use client"

import * as React from "react"
import { cn } from "cn"
import { Label as LabelPrimitive } from "radix-ui"

function Label({
  className,
  ...props
}: React.ComponentProps<typeof LabelPrimitive.Root>) {
  return (
    <LabelPrimitive.Root
      data-slot="label"
      className={cn(
        "flex items-center gap-2 text-sm leading-none font-medium select-none group-data-[disabled=true]:pointer-events-none group-data-[disabled=true]:opacity-50 peer-disabled:cursor-not-allowed peer-disabled:opacity-50",
        className
      )}
      {...props}
    />
  )
}

export { Label }
